 2	function sorted(a: array<int>) : bool
 3	    reads a
 4	{
 5	   forall i,j : int :: 0 <= i < j < a.Length ==> a[i] <= a[j]
 6	}
 7	
 8	method BinarySearch(a: array<int>, x: int) returns (index: int)
 9	    requires sorted(a)
10	    ensures 0 <= index < a.Length ==> a[index] == x
11	    ensures index == -1 ==> forall i : int :: 0 <= i < a.Length ==> a[i] != x
12	{
13	    var low := 0;
14	    var high := a.Length - 1;
15	    var mid := 0;
16	    
17	    while (low <= high) 
18	        invariant 0 <= low <= high + 1 <= (a.Length) + 1
19	        invariant x !in a[..low] && x !in a[high + 1..]
20	    {
21	        mid := (high + low) / 2;
22	        if a[mid] < x {
23	            low := mid + 1;
24	        }
25	        else if a[mid] > x {
26	            high := mid - 1;
27	        }
28	        else {
29	            return mid;
30	        }
31	    }
32	    return -1;
33	}

